    try:
        body, content_type = Request._encode_files(files, None)
        print("Success!")
        print(f"Body: {body}")
        print(f"Content-Type: {content_type}")
    except Exception as e:
        print(f"Error: {e}")
        import traceback
        traceback.print_exc()

if __name__ == "__main__":
